/* eslint-disable jsx-a11y/img-redundant-alt */
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import {
  clearSelectedProduct,
  fetchProductByIdAsync,
  resetProductFetchStatus,
  selectProductFetchStatus,
  selectSelectedProduct,
} from "../ProductSlice";
import {
  Box,
  Checkbox,
  Rating,
  Stack,
  Typography,
  useMediaQuery,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
} from "@mui/material";
import {
  addToCartAsync,
  resetCartItemAddStatus,
  selectCartItemAddStatus,
  selectCartItems,
} from "../../cart/CartSlice";
import { selectLoggedInUser } from "../../auth/AuthSlice";
import {
  fetchReviewsByProductIdAsync,
  resetReviewFetchStatus,
  selectReviewFetchStatus,
  selectReviews,
} from "../../review/ReviewSlice";
import { Reviews } from "../../review/components/Reviews";
import { toast } from "react-toastify";
import { MotionConfig, motion } from "framer-motion";
import FavoriteBorder from "@mui/icons-material/FavoriteBorder";
import LocalShippingOutlinedIcon from "@mui/icons-material/LocalShippingOutlined";
import CachedOutlinedIcon from "@mui/icons-material/CachedOutlined";
import Favorite from "@mui/icons-material/Favorite";
import InventoryIcon from "@mui/icons-material/Inventory";
import {
  createWishlistItemAsync,
  deleteWishlistItemByIdAsync,
  resetWishlistItemAddStatus,
  resetWishlistItemDeleteStatus,
  selectWishlistItemAddStatus,
  selectWishlistItemDeleteStatus,
  selectWishlistItems,
} from "../../wishlist/WishlistSlice";
import { useTheme } from "@mui/material";
import Lottie from "lottie-react";
import { loadingAnimation } from "../../../assets";
import SizeChartModal from "../../../constants/SizeChartModal";
import ImageSlider from "../../../components/ImageSlider";

const SIZES = ["XS", "S", "M", "L", "XL"];
// const COLORS = ["#020202", "#F6F6F6", "#B82222", "#BEA9A9", "#E2BB8D"];

export const ProductDetails = () => {
  const navigate = useNavigate();

  const { id } = useParams();

  const product = useSelector(selectSelectedProduct);
  const loggedInUser = useSelector(selectLoggedInUser);
  const dispatch = useDispatch();
  const cartItems = useSelector(selectCartItems);
  const cartItemAddStatus = useSelector(selectCartItemAddStatus);
  const [quantity, setQuantity] = useState(1);
  const [selectedSize, setSelectedSize] = useState("");
  const [selectedColorIndex, setSelectedColorIndex] = useState(-1);
  const reviews = useSelector(selectReviews);
  const [selectedImageIndex, setSelectedImageIndex] = useState(0);
  const theme = useTheme();
  const is1420 = useMediaQuery(theme.breakpoints.down(1420));
  const is990 = useMediaQuery(theme.breakpoints.down(990));
  const is840 = useMediaQuery(theme.breakpoints.down(840));
  const is500 = useMediaQuery(theme.breakpoints.down(500));
  const is480 = useMediaQuery(theme.breakpoints.down(480));
  const is387 = useMediaQuery(theme.breakpoints.down(387));
  const is340 = useMediaQuery(theme.breakpoints.down(340));

  const [isSizeChartOpen, setIsSizeChartOpen] = useState(false);

  const wishlistItems = useSelector(selectWishlistItems);

  const isProductAlreadyInCart = cartItems.some(
    (item) => item?.product?._id === id && item.size === selectedSize
  );
  const isProductAlreadyinWishlist = wishlistItems.some(
    (item) => item?.product?._id === id
  );

  const productFetchStatus = useSelector(selectProductFetchStatus);
  const reviewFetchStatus = useSelector(selectReviewFetchStatus);

  const totalReviewRating = reviews.reduce(
    (acc, review) => acc + review.rating,
    0
  );
  const totalReviews = reviews.length;
  const averageRating = parseInt(Math.ceil(totalReviewRating / totalReviews));

  const wishlistItemAddStatus = useSelector(selectWishlistItemAddStatus);
  const wishlistItemDeleteStatus = useSelector(selectWishlistItemDeleteStatus);

  useEffect(() => {
    window.scrollTo({
      top: 0,
      behavior: "instant",
    });
  }, []);

  useEffect(() => {
    if (id) {
      dispatch(fetchProductByIdAsync(id));
      dispatch(fetchReviewsByProductIdAsync(id));
    }
  }, [id]);

  useEffect(() => {
    if (cartItemAddStatus === "fulfilled") {
      toast.success("Product added to cart");
    } else if (cartItemAddStatus === "rejected") {
      toast.error("Error adding product to cart, please try again later");
    }
  }, [cartItemAddStatus]);

  useEffect(() => {
    if (wishlistItemAddStatus === "fulfilled") {
      toast.success("Product added to wishlist");
    } else if (wishlistItemAddStatus === "rejected") {
      toast.error("Error adding product to wishlist, please try again later");
    }
  }, [wishlistItemAddStatus]);

  useEffect(() => {
    if (wishlistItemDeleteStatus === "fulfilled") {
      toast.success("Product removed from wishlist");
    } else if (wishlistItemDeleteStatus === "rejected") {
      toast.error(
        "Error removing product from wishlist, please try again later"
      );
    }
  }, [wishlistItemDeleteStatus]);

  useEffect(() => {
    if (productFetchStatus === "rejected") {
      toast.error("Error fetching product details, please try again later");
    }
  }, [productFetchStatus]);

  useEffect(() => {
    if (reviewFetchStatus === "rejected") {
      toast.error("Error fetching product reviews, please try again later");
    }
  }, [reviewFetchStatus]);

  //lunu
  const allOutOfStock = Object.values(product?.stockQuantity || {}).every(qty => qty === 0);


  useEffect(() => {
    return () => {
      dispatch(clearSelectedProduct());
      dispatch(resetProductFetchStatus());
      dispatch(resetReviewFetchStatus());
      dispatch(resetWishlistItemDeleteStatus());
      dispatch(resetWishlistItemAddStatus());
      dispatch(resetCartItemAddStatus());
    };
  }, [dispatch]);

  const handleAddToCart = () => {
    if (!loggedInUser) {
      navigate("/login");
      return;
    }

    if (!selectedSize) {
      toast.error("Please select a size before adding to cart");
      return;
    }

    const availableStock = product?.stockQuantity[selectedSize] || 0;

    if (availableStock === 0) {
      toast.error("Selected size is out of stock");
      return;
    }

    const item = {
      user: loggedInUser._id,
      product: id,
      quantity,
      size: selectedSize,
    };
    dispatch(addToCartAsync(item));
    setQuantity(1);
  };

  const handleDecreaseQty = () => {
    if (quantity > 1) {
      setQuantity(quantity - 1);
    }
  };

  const handleIncreaseQty = () => {
    if (!selectedSize) {
      toast.error("Please select a size");
      return;
    }

    //ensuring the user does not exceed the stock quantiity of hte selected size
    const availableStock = product?.stockQuantity[selectedSize] || 0;

    if (quantity < 20 && quantity < availableStock) {
      setQuantity(quantity + 1);
    } else {
      toast.warn("Maximum quantity reached for this size");
    }
  };

  const handleSizeSelect = (size) => {
    setSelectedSize(size);
    setQuantity(1); 
  };

  const handleAddRemoveFromWishlist = (e) => {
    if (e.target.checked) {
      const data = { user: loggedInUser?._id, product: id };
      dispatch(createWishlistItemAsync(data));
    } else if (!e.target.checked) {
      const index = wishlistItems.findIndex((item) => item?.product?._id === id);
      dispatch(deleteWishlistItemByIdAsync(wishlistItems[index]._id));
    }
  };

  const totalStock = Object.values(product?.stockQuantity || {}).reduce(
  (acc, qty) => acc + qty,
  0
);

  return (
    <>
      {!(
        productFetchStatus === "rejected" && reviewFetchStatus === "rejected"
      ) && (
        <Stack
          sx={{
            justifyContent: "center",
            alignItems: "center",
            mb: "2rem",
            rowGap: "2rem",
          }}
        >
          {(productFetchStatus || reviewFetchStatus) === "pending" ? (
            <Stack
              width={is500 ? "35vh" : "25rem"}
              height={"calc(100vh - 4rem)"}
              justifyContent={"center"}
              alignItems={"center"}
            >
              <Lottie animationData={loadingAnimation} />
            </Stack>
          ) : (
            <Stack>
              {/* product details */}
              <Stack
                width={is480 ? "auto" : is1420 ? "auto" : "88rem"}
                p={is480 ? 2 : 0}
                height={is840 ? "auto" : "50rem"}
                rowGap={5}
                mt={is840 ? 0 : 5}
                justifyContent={"center"}
                mb={5}
                flexDirection={is840 ? "column" : "row"}
                columnGap={is990 ? "2rem" : "5rem"}
              >
                {/* left stack (images) */}
                <Stack
                  sx={{
                    flexDirection: "row",
                    columnGap: "2.5rem",
                    alignSelf: "flex-start",
                    height: "100%",
                  }}
                >
                  {/* image selection */}
                  {!is1420 && (
                    <Stack
                      sx={{
                        display: "flex",
                        rowGap: "1.5rem",
                        height: "100%",
                        overflowY: "scroll",
                      }}
                    >
                      {product &&
                        product.images.map((image, index) => (
                          <motion.div
                            whileHover={{ scale: 1.1 }}
                            whileTap={{ scale: 1 }}
                            style={{ width: "200px", cursor: "pointer" }}
                            onClick={() => setSelectedImageIndex(index)}
                          >
                            <img
                              style={{ width: "100%", objectFit: "contain" }}
                              src={image}
                              alt={`${product.title} image`}
                            />
                          </motion.div>
                        ))}
                    </Stack>
                  )}

                  {/* selected image */}
                  <Stack mt={is480 ? "0rem" : "5rem"}>
                    {is1420 ? (
                      <Stack width={is480 ? "100%" : is990 ? "400px" : "500px"}>
                        <ImageSlider images={product?.images || []} />
                      </Stack>
                    ) : (
                      <div style={{ width: "70%" }}>
                        <img
                          style={{
                            width: "100%",
                            objectFit: "contain",
                            aspectRatio: 1 / 0.8,
                            maxHeight: "650px",
                            margin:"0 auto",
                            display: "block",
                          }}
                          src={product?.images[selectedImageIndex]}
                          alt={`${product?.title} image`}
                        />
                      </div>
                    )}
                  </Stack>
                </Stack>

                {/* right stack - about product */}
                <Stack rowGap={"1.5rem"} width={is480 ? "100%" : "25rem"}>
                  {/* title rating price */}
                  <Stack rowGap={".5rem"}>
                    {/* title */}
                    <Typography variant="h4" fontWeight={600}>
                      {product?.title}
                    </Typography>

                    {/* rating */}
                    <Stack
                      sx={{
                        flexDirection: "row",
                        columnGap: is340 ? ".5rem" : "1rem",
                        alignItems: "center",
                        flexWrap: "wrap",
                        rowGap: "1rem",
                      }}
                    >
                      <Rating value={averageRating} readOnly />
                      <Typography>
                        ({" "}
                        {totalReviews === 0
                          ? "No reviews"
                          : totalReviews === 1
                          ? `${totalReviews} Review`
                          : `${totalReviews} Reviews`}{" "}
                        )
                      </Typography>
                      <Typography
                        color={
                          totalStock<= 10
                            ? "error"
                            : totalStock <= 20
                            ? "orange"
                            : "green"
                        }
                      >
                       {totalStock === 0 ? "Out of Stock" :
                       totalStock <= 10
  ? `Only ${totalStock} left`
  : totalStock <= 20
  ? "Only few left"
  : "In Stock"}
                      </Typography>
                    </Stack>

                    {/* price */}
                    <Typography variant="h5">AED {product?.price}</Typography>
                  </Stack>

                  {/* description */}
                  <Stack rowGap={".8rem"}>
                    <Typography>{product?.description}</Typography>
                    <hr />
                  </Stack>

                  {/* color, size and add-to-cart */}

                  {!loggedInUser?.isAdmin && (
                    <Stack sx={{ rowGap: "1.3rem" }} width={"fit-content"}>
                      {/* size */}
                      <Stack
                        flexDirection={"row"}
                        alignItems={"center"}
                        columnGap={is387 ? "5px" : "1rem"}
                        width={"fit-content"}
                      >
                        <Typography>Size: </Typography>
                        <Stack
                          flexDirection={"row"}
                          columnGap={is387 ? ".5rem" : "1rem"}
                        >
                          {SIZES.map((size) => (
                            <motion.div
                              onClick={() =>
                                product?.stockQuantity[size] > 0 &&
                                handleSizeSelect(size)
                              }
                              whileHover={
                                product?.stockQuantity[size] > 0
                                  ? { scale: 1.05 }
                                  : {}
                              }
                              whileTap={
                                product?.stockQuantity[size] > 0
                                  ? { scale: 1 }
                                  : {}
                              }
                              style={{
                                border:
                                  selectedSize === size
                                    ? "2px solid #DB4444"
                                    : "1px solid grayText",
                                borderRadius: "8px",
                                width: "30px",
                                height: "30px",
                                display: "flex",
                                justifyContent: "center",
                                alignItems: "center",
                                cursor:
                                  product?.stockQuantity[size] > 0
                                    ? "pointer"
                                    : "not-allowed",
                                padding: "1.2rem",
                                backgroundColor:
                                  selectedSize === size
                                    ? "#DB4444"
                                    : product?.stockQuantity[size]
                                    ? "whitesmoke"
                                    : "#f5f5f5",
                                color: selectedSize === size ? "white" : "",
                                opacity:
                                  product?.stockQuantity[size] > 0 ? 1 : 0.6,
                              }}
                            >
                              <p>{size}</p>
                            </motion.div>
                          ))}
                          <motion.div onClick={() => setIsSizeChartOpen(true)}>
                            <p>Size Guide</p>
                          </motion.div>
                          {/* <SizeChartModal
                            isOpen={isSizeChartOpen}
                            onClose={() => setIsSizeChartOpen(false)}
                            category={product?.category?.name}
                            subCategory={product?.subcategory?.name}
                          /> */}
                        </Stack>
                      </Stack>

                      {/* quantity , add to cart and wishlist */}
                      <Stack
                        flexDirection={"row"}
                        columnGap={is387 ? ".3rem" : "1.5rem"}
                        width={"100%"}
                      >
                        {/* qunatity */}
                        <Stack
                          flexDirection={"row"}
                          alignItems={"center"}
                          justifyContent={"space-between"}
                        >
                          <MotionConfig
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 1 }}
                          >
                            <motion.button
                              onClick={handleDecreaseQty}
                              style={{
                                padding: "10px 15px",
                                fontSize: "1.050rem",
                                backgroundColor: "",
                                color: "black",
                                outline: "none",
                                border: "1px solid black",
                                borderRadius: "8px",
                              }}
                            >
                              -
                            </motion.button>
                            <p
                              style={{
                                margin: "0 1rem",
                                fontSize: "1.1rem",
                                fontWeight: "400",
                              }}
                            >
                              {quantity}
                            </p>
                            <motion.button
                              onClick={handleIncreaseQty}
                              style={{
                                padding: "10px 15px",
                                fontSize: "1.050rem",
                                backgroundColor: "black",
                                color: "white",
                                outline: "none",
                                border: "none",
                                borderRadius: "8px",
                              }}
                            >
                              +
                            </motion.button>
                          </MotionConfig>
                        </Stack>

                        {/* add to cart */}
                        {isProductAlreadyInCart ? (
                          <button
                            style={{
                              padding: "10px 15px",
                              fontSize: "1.050rem",
                              backgroundColor: "black",
                              color: "white",
                              outline: "none",
                              border: "none",
                              borderRadius: "8px",
                            }}
                          >
                            In Cart
                          </button>
                        ) : (
                        <motion.button
  whileHover={{ scale: 1.05 }}
  whileTap={{ scale: 1 }}
  onClick={handleAddToCart}
  style={{
    padding: is387 ? "8px 12px" : "10px 15px",
    fontSize: "1.050rem",
    backgroundColor: "black",
    color: "white",
    outline: "none",
    border: "none",
    borderRadius: "8px",
    flex: is480 ? "1 1 auto" : "0 1 auto",
  }}
  disabled={
    allOutOfStock ||
    !selectedSize ||
    (selectedSize && product?.stockQuantity[selectedSize] <= 0)
  }
>
  {allOutOfStock
    ? "Out of Stock"
    : !selectedSize
    ? "Select Size"
    : product?.stockQuantity?.[selectedSize] <= 0
    ? "Out of Stock"
    : "Add to Cart"}
</motion.button>

                        )}

                        {/* wishlist */}
                        <motion.div
                          style={{
                            border: "1px solid grayText",
                            borderRadius: "4px",
                            display: "flex",
                            justifyContent: "center",
                            alignItems: "center",
                          }}
                        >
                          <Checkbox
                            checked={isProductAlreadyinWishlist}
                            onChange={(e) => handleAddRemoveFromWishlist(e)}
                            icon={<FavoriteBorder />}
                            checkedIcon={<Favorite sx={{ color: "red" }} />}
                          />
                        </motion.div>
                      </Stack>
                    </Stack>
                  )}

                  {/* Product perks for customers / Stock per variant for admin */}
                  {loggedInUser?.isAdmin ? (
                    // Admin view - Stock per variant table
                    <Stack
                      mt={3}
                      sx={{
                        justifyContent: "center",
                        alignItems: "center",
                        border: "1px grayText solid",
                        borderRadius: "7px",
                      }}
                    >
                      <Stack
                        p={2}
                        width={"100%"}
                        justifyContent={"flex-start"}
                      >
                        <Typography variant="h6" sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                          <InventoryIcon sx={{ mr: 1 }} /> Stock Per Variant
                        </Typography>
                        
                        <TableContainer component={Paper} sx={{ maxHeight: 300 }}>
                          <Table size="small" aria-label="stock table">
                            <TableHead>
                              <TableRow>
                                <TableCell>Size</TableCell>
                                <TableCell align="right">Available Stock</TableCell>
                                <TableCell align="right">Status</TableCell>
                              </TableRow>
                            </TableHead>
                            <TableBody>
                              {SIZES.map((size) => (
                                <TableRow key={size}>
                                  <TableCell component="th" scope="row">
                                    {size}
                                  </TableCell>
                                  <TableCell align="right">
                                    {product?.stockQuantity[size] || 0}
                                  </TableCell>
                                  <TableCell 
                                    align="right"
                                    sx={{ 
                                      color: (product?.stockQuantity[size] || 0) <= 0 
                                        ? "error.main" 
                                        : (product?.stockQuantity[size] || 0) <= 5 
                                          ? "warning.main" 
                                          : "success.main"
                                    }}
                                  >
                                    {(product?.stockQuantity[size] || 0) <= 0
                                      ? "Out of Stock"
                                      : (product?.stockQuantity[size] || 0) <= 5
                                        ? "Low Stock"
                                        : "In Stock"}
                                  </TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        </TableContainer>
                      </Stack>
                    </Stack>
                  ) : (
                    // Customer view - Product perks
                    <Stack
                      mt={3}
                      sx={{
                        justifyContent: "center",
                        alignItems: "center",
                        border: "1px grayText solid",
                        borderRadius: "7px",
                      }}
                    >
                      <Stack
                        p={2}
                        flexDirection={"row"}
                        alignItems={"center"}
                        columnGap={"1rem"}
                        width={"100%"}
                        justifyContent={"flex-sart"}
                      >
                        <Box>
                          <LocalShippingOutlinedIcon />
                        </Box>
                        <Stack>
                          <Typography>Free Delivery</Typography>
                          <Typography>
                            Enter your postal for delivery availabity
                          </Typography>
                        </Stack>
                      </Stack>
                      <hr style={{ width: "100%" }} />
                      <Stack
                        p={2}
                        flexDirection={"row"}
                        alignItems={"center"}
                        width={"100%"}
                        columnGap={"1rem"}
                        justifyContent={"flex-start"}
                      >
                        <Box>
                          <CachedOutlinedIcon />
                        </Box>
                        <Stack>
                          <Typography>Return Delivery</Typography>
                          <Typography>Free 30 Days Delivery Returns</Typography>
                        </Stack>
                      </Stack>
                    </Stack>
                  )}
                </Stack>
              </Stack>

              {/* reviews */}
              <Stack width={is1420 ? "auto" : "88rem"} p={is480 ? 2 : 0}>
                <Reviews productId={id} averageRating={averageRating} />
              </Stack>
            </Stack>
          )}
        </Stack> 
      )} 
    </>
  );
};